export function adminPage(canManageAdmins=false){return `<!doctype html><html lang="ka"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Hungryman — ადმინისტრაცია</title><link rel="icon" href="/assets/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="48x48" href="/assets/favicon-48.png"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400..900&family=Noto+Sans+Georgian:wght@400..900&display=swap"><link rel="stylesheet" href="/styles.css?v=perf-13"><link rel="stylesheet" href="/admin.css?v=12"><script type="module" src="/admin.js?v=12"></script></head><body class="admin-body"><div class="admin-shell"><aside class="admin-sidebar"><a href="/" class="admin-brand"><img src="/assets/hungryman-logo-360.webp" alt="Hungryman"><span>მართვის პანელი</span></a><nav aria-label="ადმინისტრაციის მენიუ">${[['overview','მიმოხილვა'],['feedback','გვირჩიე რამე'],['applications','განაცხადები'],['castings','კასტინგები'],['sponsors','სპონსორები'],['emails','ბიზნეს ფოსტა'],['sales','გაყიდვები'],...(canManageAdmins?[['youtube','YouTube ანალიტიკა'],['administrators','ადმინისტრატორები']]:[])].map(([id,label])=>`<a href="#${id}" data-tab="${id}">${label}</a>`).join('')}</nav><a href="/" class="admin-back">← საიტზე დაბრუნება</a></aside><main class="admin-main"><header class="admin-heading"><div><p class="admin-eyebrow">HUNGRYMAN / ადმინისტრაცია</p><h1 id="admin-title">მიმოხილვა</h1></div><span class="admin-private">პირადი სივრცე</span></header><div id="admin-notice" role="status" hidden></div><div id="admin-content" aria-live="polite"><p class="admin-empty">მონაცემები იტვირთება…</p></div></main></div><dialog id="admin-dialog" class="admin-dialog"><button class="dialog-x" type="button" aria-label="დახურვა">×</button><div id="dialog-body"></div></dialog></body></html>`}
